import Navbar from "@components/layout/navbar";
import Sidebar from "@components/layout/sidebar";

export default function ChatLayout({
    children,
}: {
    children: React.ReactNode;
}) {
    return (
        <div className="grid grid-rows-[50px_1fr] h-full w-full bg-bg text-text-secondary overflow-hidden">
            <nav className="h-full w-full">
                <Navbar />
            </nav>
            <div className="grid grid-cols-[60px_1fr] h-full w-full">
                <div className="shrink-0 transition-all duration-750 ease-in-out 
            max-[910px]:bg-bg-secondary max-[910px]:absolute 
            max-[910px]:w-full max-[910px]:min-w-[380px]"
                >
                    <Sidebar />
                </div>
                <section className="h-full w-full flex flex-col  justify-center align-center roun pr-5">
                    <main className="flex flex-col justify-center h-full 
                        w-full bg-bg-secondary mb-5 rounded-[25px]">
                        {children}
                    </main>
                </section>
            </div>
        </div>
    );
}